FUNCTION MEMCPY : UDINT
VAR_INPUT
    destAddr : POINTER TO BYTE;
    srcAddr : POINTER TO BYTE;
    n : UDINT;
END_VAR
VAR
    i : UDINT;
    d : POINTER TO BYTE;
    s : POINTER TO BYTE;
END_VAR
d := destAddr;
s := srcAddr;
i := 0;
WHILE i < n DO
    d^ := s^;
    d := d + 1;
    s := s + 1;
    i := i + 1;
END_WHILE
END_FUNCTION

